  ('flight-booking', 'Plane', 'Flight Booking', 'Expert route planning with best fares across all major airlines worldwide.', 'Best fares. Every route. Every airline.', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?w=800&q=80', 'Most Booked', true, '{}'::jsonb, 0, 'published'),
  ('forex', 'Banknote', 'Forex & Currency', 'Secure, competitive currency exchange for all your travel destinations.', 'Competitive rates. Instant exchange.', 'https://images.unsplash.com/photo-1580519542036-c47de6196ba5?w=800&q=80', 'Best Rates', true, '{}'::jsonb, 1, 'published'),
  ('travel-insurance', 'Shield', 'Travel Insurance', 'Comprehensive coverage for medical emergencies, trip cancellations, and lost baggage.', 'Travel worry-free.', 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&q=80', null, true, '{}'::jsonb, 2, 'published'),
  ('visa-assistance', 'FileCheck', 'Visa Assistance', 'End-to-end visa processing for 50+ countries.', '99% success rate.', 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&q=80', null, false, '{}'::jsonb, 3, 'published'),
  ('passport-assistance', 'FileCheck', 'Passport Assistance', 'Fresh passports, renewals and re-issue handled end to end.', 'Your passport, sorted.', 'https://images.unsplash.com/photo-1544717305-2782549b5136?w=800&q=80', 'Fast Track', false, '{}'::jsonb, 3, 'published'),
  ('hotel-reservation', 'Building2', 'Hotel Reservation', 'Handpicked hotels and resorts worldwide.', 'Best rates guaranteed.', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=80', null, false, '{}'::jsonb, 4, 'published'),
  ('cruise-booking', 'Ship', 'Cruise Booking', 'Luxury cruise packages across the globe.', 'Sail in style.', 'https://images.unsplash.com/photo-1548574505-5e239809ee19?w=800&q=80', null, false, '{}'::jsonb, 5, 'published');
