  ('island-hopping-greece', 'The Ultimate Guide to Island Hopping in Greece', 'Destination Guides', 'Discover the best Greek islands.', '<p>Explore Santorini, Mykonos, and Crete with our expert guide.</p>', 'https://images.unsplash.com/photo-1613395877344-13d4a8e0d49e?auto=format&fit=crop&q=80&w=800', 'Elena R.', '2023-10-15', 0, 'published'),
  ('pack-european-tour', 'How to Pack for a Two-Week European Tour', 'Travel Tips', 'Pack smart for Europe.', '<p>Essential packing tips for a two-week European adventure.</p>', 'https://images.unsplash.com/photo-1553531384-cc64ac80f931?auto=format&fit=crop&q=80&w=800', 'Mark T.', '2023-10-10', 1, 'published'),
