  insert into public.faq_categories (name, sort_order, status) values ('Booking & Payment', 0, 'published') returning id into cat_id;
  insert into public.faq_items (category_id, question, answer, sort_order) values (cat_id, 'What payment methods do you accept?', 'We accept all major credit cards, PayPal, and direct bank transfers.', 0);
  insert into public.faq_items (category_id, question, answer, sort_order) values (cat_id, 'Is my payment secure?', 'Yes, all our payments are processed securely through bank-grade encrypted payment gateways.', 1);
  insert into public.faq_items (category_id, question, answer, sort_order) values (cat_id, 'Can I pay in installments?', 'Yes, for packages booked at least 6 months in advance, we offer a 3-part flexible payment plan.', 2);
  insert into public.faq_categories (name, sort_order, status) values ('Visas & Documentation', 1, 'published') returning id into cat_id;
  insert into public.faq_items (category_id, question, answer, sort_order) values (cat_id, 'Do you guarantee visa approval?', 'While we ensure your application is perfect, the final decision rests with the respective consulate.', 0);
  insert into public.faq_items (category_id, question, answer, sort_order) values (cat_id, 'How long does an E-Visa take?', 'E-Visa processing times vary by country but generally take between 2 to 5 working days.', 1);
  insert into public.faq_categories (name, sort_order, status) values ('Travel & Accommodations', 2, 'published') returning id into cat_id;
  insert into public.faq_items (category_id, question, answer, sort_order) values (cat_id, 'Are flights included in the packages?', 'Our standard packages exclude international flights to give you flexibility.', 0);
  insert into public.faq_items (category_id, question, answer, sort_order) values (cat_id, 'Can I customize an existing package?', 'Absolutely. All our itineraries are fully customizable.', 1);
